package io.invenlio.catalog;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/brands") class BrandController {private final CatalogService service;BrandController(CatalogService s){service=s;}@PostMapping BrandView create(@Valid @RequestBody Request r){return view(service.createBrand(r.name()));}@GetMapping Page<BrandView> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.brands(page,size).map(BrandController::view);}@PatchMapping("/{id}")BrandView update(@PathVariable UUID id,@Valid @RequestBody Request r){return view(service.updateBrand(id,r.name(),r.version()));}@PostMapping("/{id}/archive")BrandView archive(@PathVariable UUID id){return view(service.archiveBrand(id));}static BrandView view(Brand b){return new BrandView(b.id(),b.name(),b.slug(),b.status().name(),b.created(),b.updated(),b.version());}record Request(@NotBlank @Size(max=120)String name,@PositiveOrZero long version){}record BrandView(UUID id,String name,String slug,String status,Instant createdAt,Instant updatedAt,long version){}}
